@Component("payout-entity-projector")
public class PayoutEntityProjector implements EntityProjector<Payout>{
		
	// core constructor
	public PayoutEntityProjector(ProjectorRegistry registry,
										PayoutRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Payout> getEntityClass() {
		return Payout.class;
	}

    /*
	 * Insert a Payout
	 * 
     * @param	entity Payout
     */
    public Payout create( Payout entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Payout
	 * 
     * @param	entity Payout
     */
    public Payout update( Payout entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Payout
	 * 
     * @param	id		UUID
     */
    public Payout delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Payout entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Seller
     * 
     * @param	parentId	UUID
     * @param	assignment 	Seller 
     * @return	Payout
     */
    public Payout assignSeller( UUID parentId, Seller assignment ) {
	    LOGGER.info("assigning Seller as " + assignment.toString() );

	    Payout parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Seller.class, assignment.getSellerId());

	    // ------------------------------------------
		// assign the Seller to the parent entity
		// ------------------------------------------ 
	    parentEntity.setSeller( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Seller
	 * 
	 * @param	parentId		UUID
	 * @return	Payout
	 */
	public Payout unAssignSeller( UUID parentId ) {
		Payout parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Seller on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Seller on the parent entithy
		// ------------------------------------------     
	    parentEntity.setSeller(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Orders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Payout
     */
    public Payout addToOrders( UUID parentId, Order addTo ) {
	    LOGGER.info("handling AssignOrdersToPayoutEvent - " );
	    
	    Payout parentEntity = repository.findById(parentId).get();
	    Order child = registry.project( Order.class, addTo.getOrderId());
	    
	    parentEntity.getOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Orders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Payout
     */
	public Payout removeFromOrders( UUID parentId, Order removeFrom ) {
	    LOGGER.info("handling RemoveOrdersFromPayoutEvent " );
	
	    Payout parentEntity = repository.findById(parentId).get();
	    Order child = registry.project( Order.class, removeFrom.getOrderId());
	    
	    parentEntity.getOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Payout via an FindPayoutQuery
     * @return 	query	FindPayoutQuery
     */
    @SuppressWarnings("unused")
    public Payout find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Payout - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Payouts
     *
     * @param	query	FindAllPayoutQuery 
     * @return 	List<Payout> 
     */
    @SuppressWarnings("unused")
    public List<Payout> findAll( FindAllPayoutQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Payout - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final PayoutRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(PayoutEntityProjector.class.getName());

}
